/**
 * Problem details (RFC 9457), served as `application/problem+json`.
 * `code`, `traceId` and `errors` are Aether-os extensions. Clients switch
 * on `code`; `detail` is for people.
 *
 */
export type CommonOpenapiProblem = {
  /**
   * `urn:aether-os:problem:<code in kebab case>`, one per `code`.
   */
  type: string;
  /**
   * Short summary, the same for every occurrence of the type.
   */
  title: string;
  /**
   * The HTTP status, repeated.
   */
  status: number;
  /**
   * Explanation of this occurrence. Safe to show; not stable.
   */
  detail: string;
  /**
   * The request path.
   */
  instance: string;
  /**
   * Stable, machine-readable code: `VALIDATION_FAILED`,
   * `INVALID_CURSOR`, `UNAUTHENTICATED`, `FORBIDDEN`, `NOT_FOUND`,
   * `VERSION_MISMATCH`, `RATE_LIMITED`, `INTERNAL`, `UNAVAILABLE`, or
   * a domain error code listed by the operation.
   *
   */
  code: string;
  /**
   * The request's trace ID, for finding it in Jaeger.
   */
  traceId: string | null;
  /**
   * One entry per invalid input (`VALIDATION_FAILED`); otherwise empty.
   */
  errors: Array<ProblemFieldError>;
};

/**
 * One invalid input. Exactly one of `pointer` and `parameter` is set.
 */
export type ProblemFieldError = {
  /**
   * JSON Pointer (RFC 6901) into the request body, e.g. `/name`.
   */
  pointer: string | null;
  /**
   * Name of the invalid query or path parameter.
   */
  parameter: string | null;
  code: 'REQUIRED' | 'UNKNOWN_FIELD' | 'INVALID';
  detail: string;
};

